{
  "microservices": [
    {
      "microservice_name": "Shipment Service",
      "responsibility": "Manages shipment registration, tracking identifier assignment, origin and destination validation, delivery deadline enforcement, and shipment lifecycle state including unrouted, routed, in transit, arrived, and collected.",
      "communicates_with": [
        "Routing Service",
        "Tracking Service",
        "Logistics Event Service"
      ]
    },
    {
      "microservice_name": "Routing Service",
      "responsibility": "Provides candidate route planning, route selection and association, trip replanning, and route reassessment when shipment destination changes or deviations occur.",
      "communicates_with": [
        "Shipment Service"
      ]
    },
    {
      "microservice_name": "Logistics Event Service",
      "responsibility": "Records logistics events (receipt, loading, unloading, customs clearance, pickup) from multiple channels, validates event associations, updates shipment operational status, recalculates transport status and plan adherence, and maintains event history for traceability.",
      "communicates_with": [
        "Shipment Service",
        "Tracking Service"
      ]
    },
    {
      "microservice_name": "Tracking Service",
      "responsibility": "Provides shipment lookup by tracking identifier, current status, last known location, estimated arrival time, event history with expected vs off-plan distinction, route deviation flags, and geographic view data.",
      "communicates_with": [
        "Shipment Service",
        "Logistics Event Service"
      ]
    }
  ]
}

{
  "microservices": [
    {
      "microservice_name": "Shipment Service",
      "responsibility": "Owns shipment registration and initiation (origin, destination, mandatory delivery deadline, unique tracking identifier, origin/destination validation) and the authoritative shipment lifecycle state (unrouted, routed, in transit, arrived, collected). Consumes validated logistics events to update operational status, recalculate transport status, known location, expected next step, and plan adherence, and to mark arrival and completion. Provides the consolidated administrative view of shipments grouped by business status and the read model for tracking.",
      "communicates_with": [
        "Routing Service",
        "Logistics Event Service"
      ]
    },
    {
      "microservice_name": "Routing Service",
      "responsibility": "Provides candidate route planning, route selection and association, trip replanning, and route reassessment when shipment destination changes or deviations occur. Encapsulates the pathfinder capability (net.java.pathfinder) as an internal implementation detail for graph traversal and route candidate generation.",
      "communicates_with": [
        "Shipment Service"
      ]
    },
    {
      "microservice_name": "Logistics Event Service",
      "responsibility": "Owns logistics event recording, validation, and event history. Validates event associations (existing shipment, location, trip; trip required for loading/unloading), rejects invalid events without altering shipment state, retains occurrence and recording times, and emits validated events for shipment state recalculation. Does not own shipment state.",
      "communicates_with": [
        "Shipment Service"
      ]
    },
    {
      "microservice_name": "Event Intake Service",
      "responsibility": "Owns multi-channel logistics event intake and channel alignment. Provides operational interface, integration service, and input-file processing channels; translates and forwards events to Logistics Event Service; separates invalid-format records for later handling without interrupting the workload; keeps monitoring channels aligned with the most recent shipment status.",
      "communicates_with": [
        "Logistics Event Service"
      ]
    },
    {
      "microservice_name": "Tracking Service",
      "responsibility": "Provides read-only shipment lookup by tracking identifier, current status, last known location, estimated arrival time, event history with expected vs off-plan distinction, route deviation flags, and geographic view data. Reads from the Shipment Service read model.",
      "communicates_with": [
        "Shipment Service"
      ]
    }
  ]
}

